// Turn Amazon's results into lead rows for the database.
const r = $input.first().json;
const q = $('Next unfinished search').first(0, $runIndex).json;
const target = $('Settings').first().json.target_new_leads;
const digits = v => String(v || '').replace(/\D/g, '').slice(-10);
const slug = v => String(v || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const rows = (r.ResultItems || []).map(p => {
  const c = p.Contacts || {};
  const phone = c.Phones?.[0]?.Value || '';
  return {
    dedupe_key: digits(phone) || slug(`${p.Title} ${p.Address?.Label || ''}`),
    name: p.Title || '',
    category: (p.Categories || []).map(x => x.Name).join(', '),
    address: p.Address?.Label || '',
    city: p.Address?.Locality || '',
    phone,
    website: c.Websites?.[0]?.Value || '',
    email: c.Emails?.[0]?.Value || '',
  };
});
return [{ json: { rows, next_token: r.NextToken || '', query_id: q.id, remaining: target - q.new_this_run } }];
